//! Emission of one JS module: type classes, then functions.
//!
//! Function bodies are emitted from Core's ANF directly. Join points become either labelled
//! blocks / `for (;;)` loops (when every jump to them happens in the same JS function) or local
//! arrow functions (when a jump happens inside a continuation closure). See ABI.md §1.

use std::cell::RefCell;
use std::collections::{BTreeSet, HashMap, HashSet};
use std::fmt::Write;

use vow_core::builtins::{self, Abi};
use vow_core::*;

use crate::sourcemap::{self, Mapping};
use crate::{Cx, RESERVED, RUNTIME_FILE, ident, js_string, module_path};

pub(crate) fn module(cx: &Cx, module: &str) -> (String, String) {
    let mut w = W {
        out: String::new(),
        line: 0,
        depth: 0,
        maps: Vec::new(),
        pending: None,
        cx,
    };
    let ns = RefCell::new(BTreeSet::new());
    for (i, t) in cx.m.types.iter().enumerate() {
        if t.module == module && t.builtin.is_none() {
            type_class(&mut w, TypeId(i as u32));
        }
    }
    let module_defs: Vec<&str> =
        cx.m.defs
            .iter()
            .enumerate()
            .filter(|(_, d)| d.module == module)
            .map(|(i, _)| cx.def_names[i].as_str())
            .collect();
    for (i, d) in cx.m.defs.iter().enumerate() {
        if d.module == module {
            let id = DefId(i as u32);
            if cx.direct[i] {
                FnEmit::new(cx, id, module, &module_defs, Mode::Direct, &ns).def(&mut w);
            }
            FnEmit::new(cx, id, module, &module_defs, Mode::Cps, &ns).def(&mut w);
        }
    }

    let path = module_path(module);
    let up = "../".repeat(path.matches('/').count());
    let rel = |p: &str| {
        if up.is_empty() {
            format!("./{p}")
        } else {
            format!("{up}{p}")
        }
    };
    let mut head = format!(
        "// Generated by vow from module {module}. Do not edit.\nimport * as $rt from \"{}\";\n",
        rel(RUNTIME_FILE)
    );
    for other in ns.borrow().iter() {
        let _ = writeln!(
            head,
            "import * as {} from \"{}\";",
            ns_name(other),
            rel(&module_path(other))
        );
    }
    head.push_str("const { G: $G, LIMIT: $L, bounce: $b, ret: $ret } = $rt;\n\n");
    let shift = head.matches('\n').count() as u32;
    let file = path.rsplit('/').next().unwrap_or(&path).to_owned();
    let maps = w
        .maps
        .iter()
        .map(|m| Mapping {
            gen_line: m.gen_line + shift,
            ..*m
        })
        .collect();
    let map = sourcemap::render(&file, &cx.sources, maps);
    let text = format!("{head}{}//# sourceMappingURL={file}.map\n", w.out);
    (text, map)
}

fn ns_name(module: &str) -> String {
    format!("${}", ident(&module.replace("::", "_").replace('/', "_")))
}

struct W<'c> {
    out: String,
    line: u32,
    depth: usize,
    maps: Vec<Mapping>,
    pending: Option<Pos>,
    cx: &'c Cx<'c>,
}

impl W<'_> {
    fn line(&mut self, s: &str) {
        if let Some(pos) = self.pending.take()
            && let Some((source, ix)) = self.cx.lines.get(&pos.file)
        {
            let (line, col) = ix.line_col(pos.offset);
            self.maps.push(Mapping {
                gen_line: self.line,
                gen_col: (self.depth * 2) as u32,
                source: *source as u32,
                line,
                col,
            });
        }
        for _ in 0..self.depth {
            self.out.push_str("  ");
        }
        self.out.push_str(s);
        self.out.push('\n');
        self.line += 1;
    }

    fn at(&mut self, pos: Option<Pos>) {
        if pos.is_some() {
            self.pending = pos;
        }
    }
}

// ---------------------------------------------------------------------------------------------
// Types

fn type_class(w: &mut W, t: TypeId) {
    let cx = w.cx;
    let td = cx.m.ty(t);
    let name = &cx.type_names[t.index()];
    let module = js_string(&td.module);
    match &td.kind {
        TypeKind::Variant { ctors } => {
            w.line(&format!("export class {name} extends $rt.Variant {{}}"));
            let cs: Vec<String> = ctors
                .iter()
                .map(|c| {
                    let hs: Vec<String> = c.fields.iter().map(|f| hint(f, true)).collect();
                    format!("[{}, [{}]]", js_string(&c.name), hs.join(", "))
                })
                .collect();
            w.line(&format!(
                "{name}.prototype.$t = $rt.variantType({}, {module}, [{}]);",
                js_string(&td.name),
                cs.join(", ")
            ));
            for (i, c) in ctors.iter().enumerate() {
                if c.fields.is_empty() {
                    w.line(&format!(
                        "export const {name}${} = Object.freeze(new {name}({i}, []));",
                        ident(&c.name)
                    ));
                }
            }
        }
        TypeKind::Record { fields, error } => {
            let params: Vec<String> = (0..fields.len()).map(|i| format!("${i}")).collect();
            w.line(&format!("export class {name} {{"));
            w.depth += 1;
            w.line(&format!("constructor({}) {{", params.join(", ")));
            w.depth += 1;
            for (i, f) in fields.iter().enumerate() {
                w.line(&format!("this.{} = ${i};", prop(&f.name)));
            }
            w.depth -= 1;
            w.line("}");
            w.depth -= 1;
            w.line("}");
            let fs: Vec<String> = fields
                .iter()
                .map(|f| {
                    format!(
                        "[{}, {}, {}]",
                        js_string(&f.name),
                        js_string(&prop(&f.name)),
                        hint(&f.ty, true)
                    )
                })
                .collect();
            w.line(&format!(
                "{name}.prototype.$t = $rt.recordType({}, {module}, [{}], {error});",
                js_string(&td.name),
                fs.join(", ")
            ));
        }
    }
    w.line(&format!(
        "$rt.def({}, {name});",
        js_string(&td.qualified_name())
    ));
    w.line("");
}

/// The JS property for a record field.
fn prop(field: &str) -> String {
    if field == "__proto__" {
        format!("{field}$")
    } else {
        field.to_owned()
    }
}

/// A `Show` type hint (ABI.md §7) as a JS literal; `null` when the type contains no `Float`.
fn hint(ty: &Ty, vars: bool) -> String {
    hint_opt(ty, vars).unwrap_or_else(|| "null".into())
}

fn hint_opt(ty: &Ty, vars: bool) -> Option<String> {
    let all = |ts: &[Ty]| -> Option<Vec<String>> {
        let hs: Vec<Option<String>> = ts.iter().map(|t| hint_opt(t, vars)).collect();
        if hs.iter().all(Option::is_none) {
            None
        } else {
            Some(
                hs.into_iter()
                    .map(|h| h.unwrap_or_else(|| "null".into()))
                    .collect(),
            )
        }
    };
    match ty {
        Ty::Float => Some("\"F\"".into()),
        Ty::Var(i) if vars => Some(format!("[\"V\", {i}]")),
        Ty::Tuple(ts) => all(ts).map(|hs| format!("[\"T\", {}]", hs.join(", "))),
        Ty::List(t) => hint_opt(t, vars).map(|h| format!("[\"L\", {h}]")),
        Ty::Set(t) => hint_opt(t, vars).map(|h| format!("[\"S\", {h}]")),
        Ty::Map(k, v) => {
            all(&[(**k).clone(), (**v).clone()]).map(|hs| format!("[\"M\", {}]", hs.join(", ")))
        }
        Ty::Adt(_, args) => all(args).map(|hs| format!("[\"A\", [{}]]", hs.join(", "))),
        _ => None,
    }
}

// ---------------------------------------------------------------------------------------------
// Functions

#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode {
    Cps,
    Direct,
}

#[derive(Default)]
struct LabelInfo {
    /// Emitted as a labelled block or loop in the defining JS function.
    inline: bool,
    /// Jumped to from its own join body (a loop).
    recursive: bool,
    params: Vec<Local>,
}

struct FnEmit<'a> {
    cx: &'a Cx<'a>,
    id: DefId,
    def: &'a FnDef,
    module: &'a str,
    mode: Mode,
    names: Vec<String>,
    labels: HashMap<Label, LabelInfo>,
    /// Inline recursive labels whose loop body is being emitted.
    in_loop: Vec<Label>,
    /// Inline recursive labels whose entry block is being emitted.
    in_entry: Vec<Label>,
    ctxs: u32,
    ns: &'a RefCell<BTreeSet<String>>,
}

impl<'a> FnEmit<'a> {
    fn new(
        cx: &'a Cx<'a>,
        id: DefId,
        module: &'a str,
        module_defs: &[&str],
        mode: Mode,
        ns: &'a RefCell<BTreeSet<String>>,
    ) -> Self {
        let def = cx.m.def(id);
        let mut taken: HashSet<String> = module_defs.iter().map(|s| (*s).to_owned()).collect();
        taken.extend(module_defs.iter().map(|s| format!("{s}$d")));
        let names = def
            .locals
            .iter()
            .map(|l| {
                let base = ident(&l.name);
                let mut name = base.clone();
                let mut n = 1;
                while taken.contains(&name) || RESERVED.contains(&name.as_str()) {
                    name = format!("{base}_{n}");
                    n += 1;
                }
                taken.insert(name.clone());
                name
            })
            .collect();
        let mut e = FnEmit {
            cx,
            id,
            def,
            module,
            mode,
            names,
            labels: HashMap::new(),
            in_loop: Vec::new(),
            in_entry: Vec::new(),
            ctxs: 0,
            ns,
        };
        e.analyze_labels();
        e
    }

    fn name(&self, l: Local) -> &str {
        &self.names[l.index()]
    }

    fn def(mut self, w: &mut W) {
        let d = self.def;
        let name = self.cx.def_names[self.id.index()].clone();
        let export = if matches!(d.kind, FnKind::Top { .. } | FnKind::Test) {
            "export "
        } else {
            ""
        };
        let mut params: Vec<String> = d
            .captures
            .iter()
            .chain(&d.params)
            .map(|l| self.name(*l).to_owned())
            .collect();
        w.at(d.pos);
        match self.mode {
            Mode::Direct => {
                w.line(&format!(
                    "{export}function {name}$d({}) {{",
                    params.join(", ")
                ));
                w.depth += 1;
                self.expr(w, &d.body, "");
                w.depth -= 1;
                w.line("}");
            }
            Mode::Cps if self.cx.direct[self.id.index()] => {
                let ps = params.join(", ");
                params.extend(["$ctx".into(), "$k".into()]);
                w.line(&format!(
                    "{export}function {name}({}) {{",
                    params.join(", ")
                ));
                w.depth += 1;
                w.line(&format!("return $ret($k, {name}$d({ps}));"));
                w.depth -= 1;
                w.line("}");
            }
            Mode::Cps => {
                params.extend(["$ctx".into(), "$k".into()]);
                let ps = params.join(", ");
                w.line(&format!("{export}function {name}({ps}) {{"));
                w.depth += 1;
                w.line(&format!("if (++$G.d > $L) return $b({name}, [{ps}]);"));
                self.expr(w, &d.body, "$ctx");
                w.depth -= 1;
                w.line("}");
            }
        }
        w.line("");
    }

    // -----------------------------------------------------------------------------------------
    // Join point analysis

    fn analyze_labels(&mut self) {
        let mut infos = HashMap::new();
        collect_labels(&self.def.body, &mut infos, &mut Vec::new());
        self.labels = infos;
        loop {
            let mut frames = Frames::default();
            self.frames(&self.def.body, 0, &mut frames);
            let mut changed = false;
            for (label, info) in self.labels.iter_mut() {
                let def_frame = frames.def.get(label).copied();
                let bad = frames.no_inline.contains(label)
                    || frames
                        .jumps
                        .get(label)
                        .is_some_and(|js| js.iter().any(|f| Some(*f) != def_frame));
                if info.inline && bad {
                    info.inline = false;
                    changed = true;
                }
            }
            if !changed {
                break;
            }
        }
        assert!(
            self.mode == Mode::Cps || self.labels.values().all(|l| l.inline),
            "direct-style bodies only use inline join points ({})",
            self.def.name
        );
    }

    fn frames(&self, e: &Expr, frame: u32, f: &mut Frames) {
        match e {
            Expr::Let { bind, body, .. } => {
                let inner = if self.is_cps(bind) { f.fresh() } else { frame };
                self.frames(body, inner, f);
            }
            Expr::Ret(_) | Expr::Fail(_) => {}
            Expr::Jump(l, _) => f.jumps.entry(*l).or_default().push(frame),
            Expr::LetJoin {
                label, join, body, ..
            } => {
                f.def.insert(*label, frame);
                let jf = if self.labels[label].inline {
                    frame
                } else {
                    f.fresh()
                };
                self.frames(join, jf, f);
                self.frames(body, frame, f);
            }
            Expr::Switch { arms, default, .. } => {
                for (_, a) in arms {
                    self.frames(a, frame, f);
                }
                if let Some(d) = default {
                    self.frames(d, frame, f);
                }
            }
            Expr::If { then, els, .. } => {
                self.frames(then, frame, f);
                self.frames(els, frame, f);
            }
            Expr::Handle { body, .. } => self.frames(body, frame, f),
            Expr::Try { on_fail, body } => {
                f.no_inline.insert(*on_fail);
                self.frames(body, frame, f);
            }
        }
    }

    /// Does this binding transfer control through a continuation?
    fn is_cps(&self, b: &Bind) -> bool {
        match b {
            Bind::Perform(..) => true,
            Bind::Call(Atom::Global(d), _) => !self.cx.direct[d.index()],
            Bind::Call(Atom::Builtin(name), _) => {
                builtins::lookup(name).is_none_or(|b| b.abi == Abi::Cps)
            }
            Bind::Call(..) => true,
            _ => false,
        }
    }

    // -----------------------------------------------------------------------------------------
    // Expressions

    fn ret(&self, value: &str) -> String {
        match self.mode {
            Mode::Cps => format!("return $ret($k, {value});"),
            Mode::Direct => format!("return {value};"),
        }
    }

    fn fresh_ctx(&mut self) -> String {
        self.ctxs += 1;
        format!("$ctx{}", self.ctxs)
    }

    fn expr(&mut self, w: &mut W, e: &Expr, ctx: &str) {
        match e {
            Expr::Let {
                local,
                bind,
                pos,
                body,
            } => {
                w.at(*pos);
                if self.is_cps(bind) {
                    self.cps_call(w, *local, bind, body, ctx);
                } else {
                    self.simple_bind(w, *local, bind);
                    self.expr(w, body, ctx);
                }
            }
            Expr::Ret(a) => {
                let s = self.ret(&self.atom(a));
                w.line(&s);
            }
            Expr::Fail(a) => {
                let s = format!("return $rt.fail({ctx}, {});", self.atom(a));
                w.line(&s);
            }
            Expr::Jump(l, args) => self.jump(w, *l, args),
            Expr::LetJoin {
                label,
                params,
                join,
                body,
            } => self.let_join(w, *label, params, join, body, ctx),
            Expr::Switch {
                scrut,
                on,
                arms,
                default,
            } => {
                let s = self.atom(scrut);
                match on {
                    SwitchOn::Variant(_) => {
                        w.line(&format!("switch ({s}.tag) {{"));
                        w.depth += 1;
                        for (key, arm) in arms {
                            w.line(&format!("case {key}: {{"));
                            w.depth += 1;
                            self.expr(w, arm, ctx);
                            w.depth -= 1;
                            w.line("}");
                        }
                        if let Some(d) = default {
                            w.line("default: {");
                            w.depth += 1;
                            self.expr(w, d, ctx);
                            w.depth -= 1;
                            w.line("}");
                        }
                        w.depth -= 1;
                        w.line("}");
                    }
                    SwitchOn::Errors(ts) => {
                        for (i, (key, arm)) in arms.iter().enumerate() {
                            let class = self.type_ref(ts[*key as usize]);
                            let kw = if i == 0 { "if" } else { "} else if" };
                            w.line(&format!("{kw} ({s} instanceof {class}) {{"));
                            w.depth += 1;
                            self.expr(w, arm, ctx);
                            w.depth -= 1;
                        }
                        match default {
                            Some(d) if arms.is_empty() => self.expr(w, d, ctx),
                            Some(d) => {
                                w.line("} else {");
                                w.depth += 1;
                                self.expr(w, d, ctx);
                                w.depth -= 1;
                                w.line("}");
                            }
                            None if arms.is_empty() => {}
                            None => w.line("}"),
                        }
                    }
                }
            }
            Expr::If { cond, then, els } => {
                w.line(&format!("if ({}) {{", self.atom(cond)));
                w.depth += 1;
                self.expr(w, then, ctx);
                w.depth -= 1;
                w.line("} else {");
                w.depth += 1;
                self.expr(w, els, ctx);
                w.depth -= 1;
                w.line("}");
            }
            Expr::Handle { handler, body } => {
                let c = self.fresh_ctx();
                w.line(&format!(
                    "const {c} = $rt.install({ctx}, {});",
                    self.atom(handler)
                ));
                self.expr(w, body, &c);
            }
            Expr::Try { on_fail, body } => {
                let c = self.fresh_ctx();
                w.line(&format!("const {c} = $rt.catcher({ctx}, j{});", on_fail.0));
                self.expr(w, body, &c);
            }
        }
    }

    fn cps_call(&mut self, w: &mut W, x: Local, bind: &Bind, body: &Expr, ctx: &str) {
        // The continuation: `$k` for a tail call, a join point for `jump j(x)`, else an arrow.
        let xs = self.name(x).to_owned();
        let k = match body {
            Expr::Ret(Atom::Local(r)) if *r == x && self.mode == Mode::Cps => Some("$k".to_owned()),
            Expr::Jump(l, args)
                if args.as_slice() == [Atom::Local(x)] && !self.labels[l].inline =>
            {
                Some(format!("j{}", l.0))
            }
            _ => None,
        };
        // `callee(args…, ctx, ` — the continuation and closing parenthesis follow.
        let head = match bind {
            Bind::Perform(e, op, args) => {
                let f = format!("$f{}", x.0);
                let eff = js_string(&self.cx.m.effect(*e).qualified_name());
                w.line(&format!("const {f} = $rt.find({ctx}, {eff});"));
                let mut a = vec![format!("{f}.i")];
                a.extend(args.iter().map(|x| self.atom(x)));
                a.push(format!("$rt.cctx({ctx}, {f})"));
                format!("{f}.i.c[{op}]({}, ", a.join(", "))
            }
            Bind::Call(callee, args) => {
                let mut a: Vec<String> = args.iter().map(|x| self.atom(x)).collect();
                a.push(ctx.to_owned());
                let f = match callee {
                    Atom::Builtin(name) => format!("$rt.{name}"),
                    other => self.atom(other),
                };
                format!("{f}({}, ", a.join(", "))
            }
            _ => unreachable!("not a CPS binding"),
        };
        match k {
            Some(k) => w.line(&format!("return {head}{k});")),
            None => {
                w.line(&format!("return {head}({xs}) => {{"));
                w.depth += 1;
                self.expr(w, body, ctx);
                w.depth -= 1;
                w.line("});");
            }
        }
    }

    fn simple_bind(&mut self, w: &mut W, x: Local, bind: &Bind) {
        let xs = self.name(x).to_owned();
        let rhs = match bind {
            Bind::Atom(a) => self.atom(a),
            Bind::Prim(op, args) => self.prim(op, args),
            Bind::Call(Atom::Global(d), args) => {
                format!("{}$d({})", self.def_ref(*d), self.atoms(args))
            }
            Bind::Call(Atom::Builtin(name), args) => format!("$rt.{name}({})", self.atoms(args)),
            Bind::Call(..) | Bind::Perform(..) => unreachable!("CPS binding"),
            Bind::Closure(d, caps) => {
                let f = self.cx.def_names[d.index()].clone();
                if caps.is_empty() {
                    f
                } else {
                    format!("{f}.bind(null, {})", self.atoms(caps))
                }
            }
            Bind::Alloc(alloc, args) => self.alloc(alloc, args),
            Bind::Proj(a, p) => {
                let a = self.atom(a);
                match p {
                    Proj::Tuple(i) => format!("{a}[{i}]"),
                    Proj::Field(t, i) => {
                        format!("{a}.{}", prop(&self.cx.m.ty(*t).fields()[*i as usize].name))
                    }
                    Proj::Payload(_, _, i) => format!("{a}.fields[{i}]"),
                }
            }
            Bind::Check(c, cond) => {
                let decl = &self.cx.m.contracts[c.index()];
                let what = match decl.kind {
                    ContractKind::Requires => "precondition",
                    ContractKind::Ensures => "postcondition",
                    ContractKind::Where => "refinement",
                };
                let msg = js_string(&format!(
                    "{what} `{}` of {} violated",
                    decl.name, self.def.name
                ));
                w.line(&format!(
                    "if (!{}) $rt.defect({}, {msg});",
                    self.atom(cond),
                    js_string(decl.defect_code())
                ));
                "undefined".into()
            }
            Bind::MakeHandler {
                effect,
                state,
                clauses,
            } => format!(
                "$rt.makeHandler({}, [{}], [{}])",
                js_string(&self.cx.m.effect(*effect).qualified_name()),
                self.atoms(state),
                self.atoms(clauses)
            ),
            Bind::StateGet(inst, i) => format!("{}.s[{i}]", self.atom(inst)),
            Bind::StateSet(inst, i, v) => {
                w.line(&format!("{}.s[{i}] = {};", self.atom(inst), self.atom(v)));
                "undefined".into()
            }
            Bind::Hole(h) => format!("$rt.defect(\"D090\", \"typed hole ?{h} was evaluated\")"),
        };
        w.line(&format!("const {xs} = {rhs};"));
    }

    fn jump(&mut self, w: &mut W, l: Label, args: &[Atom]) {
        let info = &self.labels[&l];
        if !info.inline {
            let s = format!("return j{}({});", l.0, self.atoms(args));
            w.line(&s);
            return;
        }
        let params = info.params.clone();
        self.assign(w, &params, args);
        if self.in_loop.contains(&l) {
            w.line(&format!("continue j{};", l.0));
        } else if self.in_entry.contains(&l) {
            w.line(&format!("break j{}$e;", l.0));
        } else {
            w.line(&format!("break j{};", l.0));
        }
    }

    /// Parallel assignment of jump arguments to an inline join's parameters.
    fn assign(&self, w: &mut W, params: &[Local], args: &[Atom]) {
        let clash = args.iter().enumerate().any(|(i, a)| {
            matches!(a, Atom::Local(l) if params.iter().position(|p| p == l).is_some_and(|j| j != i))
        });
        if clash {
            let tmps: Vec<String> = args
                .iter()
                .enumerate()
                .map(|(i, a)| format!("$t{i} = {}", self.atom(a)))
                .collect();
            w.line(&format!("const {};", tmps.join(", ")));
            for (i, p) in params.iter().enumerate() {
                w.line(&format!("{} = $t{i};", self.name(*p)));
            }
        } else {
            for (p, a) in params.iter().zip(args) {
                if *a != Atom::Local(*p) {
                    w.line(&format!("{} = {};", self.name(*p), self.atom(a)));
                }
            }
        }
    }

    fn let_join(
        &mut self,
        w: &mut W,
        label: Label,
        params: &[Local],
        join: &Expr,
        body: &Expr,
        ctx: &str,
    ) {
        let info = &self.labels[&label];
        let (inline, recursive) = (info.inline, info.recursive);
        let ps: Vec<String> = params.iter().map(|p| self.name(*p).to_owned()).collect();
        let ps = ps.join(", ");
        let j = format!("j{}", label.0);
        if !inline {
            w.line(&format!("const {j} = ({ps}) => {{"));
            w.depth += 1;
            if recursive {
                w.line(&format!("if (++$G.d > $L) return $b({j}, [{ps}]);"));
            }
            self.expr(w, join, ctx);
            w.depth -= 1;
            w.line("};");
            self.expr(w, body, ctx);
            return;
        }
        if !params.is_empty() {
            w.line(&format!("let {ps};"));
        }
        // Entry: run `body`; its jumps to `label` fall through to the join code below.
        let entry_label = if recursive {
            format!("{j}$e")
        } else {
            j.clone()
        };
        match body {
            Expr::Jump(l, args) if *l == label => self.assign(w, params, args),
            _ => {
                w.line(&format!("{entry_label}: {{"));
                w.depth += 1;
                if recursive {
                    self.in_entry.push(label);
                }
                self.expr(w, body, ctx);
                if recursive {
                    self.in_entry.pop();
                }
                w.depth -= 1;
                w.line("}");
            }
        }
        if recursive {
            w.line(&format!("{j}: for (;;) {{"));
            w.depth += 1;
            self.in_loop.push(label);
            self.expr(w, join, ctx);
            self.in_loop.pop();
            w.depth -= 1;
            w.line("}");
        } else {
            self.expr(w, join, ctx);
        }
    }

    // -----------------------------------------------------------------------------------------
    // Atoms and operators

    fn atoms(&self, atoms: &[Atom]) -> String {
        atoms
            .iter()
            .map(|a| self.atom(a))
            .collect::<Vec<_>>()
            .join(", ")
    }

    fn atom(&self, a: &Atom) -> String {
        match a {
            Atom::Local(l) => self.name(*l).to_owned(),
            Atom::Lit(lit) => lit_js(lit),
            Atom::Global(d) => self.def_ref(*d),
            Atom::Builtin(name) => match builtins::lookup(name) {
                Some(b) if b.abi == Abi::Direct => {
                    let ps: Vec<String> = (0..b.arity).map(|i| format!("$a{i}")).collect();
                    let ps = ps.join(", ");
                    let sep = if ps.is_empty() { "" } else { ", " };
                    format!("(({ps}{sep}$ctx, $k) => $ret($k, $rt.{name}({ps})))")
                }
                _ => format!("$rt.{name}"),
            },
        }
    }

    fn def_ref(&self, d: DefId) -> String {
        let name = &self.cx.def_names[d.index()];
        let module = &self.cx.m.def(d).module;
        if module == self.module {
            name.clone()
        } else {
            format!("{}.{name}", self.import(module))
        }
    }

    fn type_ref(&self, t: TypeId) -> String {
        let name = &self.cx.type_names[t.index()];
        let module = &self.cx.m.ty(t).module;
        if module == self.module {
            name.clone()
        } else {
            format!("{}.{name}", self.import(module))
        }
    }

    fn import(&self, module: &str) -> String {
        self.ns.borrow_mut().insert(module.to_owned());
        ns_name(module)
    }

    fn alloc(&mut self, alloc: &Alloc, args: &[Atom]) -> String {
        let a = self.atoms(args);
        match alloc {
            Alloc::Tuple => format!("[{a}]"),
            Alloc::List => format!("$rt.list([{a}])"),
            Alloc::Record(t) => format!("new {}({a})", self.type_ref(*t)),
            Alloc::Variant(t, c) => {
                let td = self.cx.m.ty(*t);
                match (td.builtin.as_deref(), c) {
                    (Some("Option"), 0) => "$rt.None".into(),
                    (Some("Option"), _) => format!("$rt.Some({a})"),
                    (Some("Result"), 0) => format!("$rt.Ok({a})"),
                    (Some("Result"), _) => format!("$rt.Err({a})"),
                    _ => {
                        let class = self.type_ref(*t);
                        if args.is_empty() {
                            format!("{class}${}", ident(&td.ctors()[*c as usize].name))
                        } else {
                            format!("new {class}({c}, [{a}])")
                        }
                    }
                }
            }
        }
    }

    fn prim(&mut self, op: &PrimOp, args: &[Atom]) -> String {
        let a: Vec<String> = args.iter().map(|x| self.atom(x)).collect();
        let bin = |o: &str| format!("({} {o} {})", a[0], a[1]);
        let cmp = |t: &CmpTy, o: &str| match t {
            CmpTy::Int | CmpTy::Float => bin(o),
            _ => format!("($rt.cmp({}, {}) {o} 0)", a[0], a[1]),
        };
        let eq = |t: &CmpTy, neg: bool| match t {
            CmpTy::Any => format!("{}$rt.eq({}, {})", if neg { "!" } else { "" }, a[0], a[1]),
            _ => bin(if neg { "!==" } else { "===" }),
        };
        match op {
            PrimOp::IntAdd => format!("$rt.add({}, {})", a[0], a[1]),
            PrimOp::IntSub => format!("$rt.sub({}, {})", a[0], a[1]),
            PrimOp::IntMul => format!("$rt.mul({}, {})", a[0], a[1]),
            PrimOp::IntDiv => format!("$rt.div({}, {})", a[0], a[1]),
            PrimOp::IntRem => format!("$rt.rem({}, {})", a[0], a[1]),
            PrimOp::IntNeg => format!("$rt.neg({})", a[0]),
            PrimOp::FloatAdd | PrimOp::Concat => bin("+"),
            PrimOp::FloatSub => bin("-"),
            PrimOp::FloatMul => bin("*"),
            PrimOp::FloatDiv => bin("/"),
            PrimOp::FloatRem => bin("%"),
            PrimOp::FloatNeg => format!("(-{})", a[0]),
            PrimOp::Not => format!("!{}", a[0]),
            PrimOp::Eq(t) => eq(t, false),
            PrimOp::Ne(t) => eq(t, true),
            PrimOp::Lt(t) => cmp(t, "<"),
            PrimOp::Le(t) => cmp(t, "<="),
            PrimOp::Gt(t) => cmp(t, ">"),
            PrimOp::Ge(t) => cmp(t, ">="),
            PrimOp::Show(ty) => match ty {
                Ty::String => a[0].clone(),
                Ty::Int | Ty::Bool => format!("String({})", a[0]),
                Ty::Float => format!("$rt.showFloat({})", a[0]),
                _ => match hint_opt(ty, false) {
                    Some(h) => format!("$rt.show({}, {h})", a[0]),
                    None => format!("$rt.show({})", a[0]),
                },
            },
        }
    }
}

#[derive(Default)]
struct Frames {
    next: u32,
    def: HashMap<Label, u32>,
    jumps: HashMap<Label, Vec<u32>>,
    no_inline: HashSet<Label>,
}

impl Frames {
    fn fresh(&mut self) -> u32 {
        self.next += 1;
        self.next
    }
}

/// Every join point with its parameters, and whether it is jumped to from its own body.
fn collect_labels(e: &Expr, infos: &mut HashMap<Label, LabelInfo>, inside: &mut Vec<Label>) {
    match e {
        Expr::Let { body, .. } | Expr::Handle { body, .. } | Expr::Try { body, .. } => {
            collect_labels(body, infos, inside)
        }
        Expr::Ret(_) | Expr::Fail(_) => {}
        Expr::Jump(l, _) => {
            if inside.contains(l)
                && let Some(i) = infos.get_mut(l)
            {
                i.recursive = true;
            }
        }
        Expr::LetJoin {
            label,
            params,
            join,
            body,
        } => {
            infos.insert(
                *label,
                LabelInfo {
                    inline: true,
                    recursive: false,
                    params: params.clone(),
                },
            );
            inside.push(*label);
            collect_labels(join, infos, inside);
            inside.pop();
            collect_labels(body, infos, inside);
        }
        Expr::Switch { arms, default, .. } => {
            for (_, a) in arms {
                collect_labels(a, infos, inside);
            }
            if let Some(d) = default {
                collect_labels(d, infos, inside);
            }
        }
        Expr::If { then, els, .. } => {
            collect_labels(then, infos, inside);
            collect_labels(els, infos, inside);
        }
    }
}

fn lit_js(lit: &Lit) -> String {
    const SAFE: i64 = (1 << 53) - 1;
    match lit {
        Lit::Unit => "undefined".into(),
        Lit::Bool(b) => b.to_string(),
        Lit::Int(i) if (-SAFE..=SAFE).contains(i) => i.to_string(),
        Lit::Int(i) => format!("$rt.unsafeInt(\"{i}\")"),
        Lit::Float(f) if f.is_nan() => "NaN".into(),
        Lit::Float(f) if f.is_infinite() => if *f > 0.0 { "Infinity" } else { "-Infinity" }.into(),
        Lit::Float(f) => format!("{f:?}"),
        Lit::String(s) => js_string(s),
    }
}
